dir:



































































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',')
	select @@fields into #t from v51 a @@join
	  where a.id in (select id from #id)
	  order by a.line, a.id

	select id_tg, line_tg, sum(a.so_luong) as sl_bao_gia into #sl from v611 a with(index(id_tg)) where id <> @id and id_tg <> 0 and exists(select 1 from #t b where a.id_tg = b.id_tg and a.line_tg = b.line_tg) group by id_tg, line_tg
	update #t set sl_cl = a.so_luong - isnull(b.sl_bao_gia, 0) from #t a left join #sl b on a.id_tg = b.id_tg and a.line_tg = b.line_tg
	update #t set so_luong0 = sl_cl
	select * from #t where sl_cl <> 0

	select a.ma_noi_di,a.ma_noi_den,a.ma_hang,a.ma_nt,a.ds_cong,b.ten_noi_di,c.ten_noi_den,a.ten_kh,e.ten_kh ten_hang,a.ngay_hl, a.ngay_hld, a.ma_gd, id id_tg from s51 a 
	  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den left join dmkh e on a.ma_hang = e.ma_kh
	where a.id in (select top 1 id from #id order by id desc) 

	drop table #id, #t









  &DefaultButton;




function filter$s611TG1Select(p){
  this.constructor(p);
}
filter$s611TG1Select.prototype = new DirEvent();
filter$s611TG1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$s611TG1Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den','ma_kh','ten_kh', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,p.options._ma_kh, p.options._ten_kh,  p.options._ma_nt, p.options._unit_id]);
	dir$s611TG1SetMaster(p);

}

function dir$s611TG1SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$s611TG1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = dt.findRow("[so_luong0] > [sl_cl]");

  var fun = function(){
    dt.removeRow('[so_luong0] == 0');
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong0');
    pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
	p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();

    return false;
}









					DECLARE @ds_cong VARCHAR(4000)  
					SELECT distinct ma_cong into #tt FROM v51 a where a.id = @id
					SELECT @ds_cong = COALESCE(@ds_cong + ', ','') + ltrim(rtrim(ma_cong)) FROM #tt

					select top 1 a.id_yc as [!id_yc], a.ma_kh as [!ma_kh],a.ten_kh as [!ten_kh],a.ma_so_thue as [!ma_so_thue],a.ma_hang as [!ma_hang], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den],
					b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den],@ds_cong as [!ds_cong], e.ten_kh as [!ten_hang],a.so_ct as [!so_ct]
					from s51 a left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den left join dmkh d on a.ma_kh =d.ma_kh left join dmkh e on a.ma_hang =e.ma_kh
					where a.id = @id

					drop table #tt
